先把“理解用户想买什么”和“有权执行什么”分开。抽取器只给候选明细，确定性策略根据可信员工身份、权限、完整度和审批要求，逐动作输出 ALLOWED、DENIED、NEEDS_APPROVAL、NEEDS_INFO。JSON 和中文解释来自同一个裁决对象，避免两个输出各说各话。 这份 Java 实现选择四个示例动作：查询目录、创建草稿、请求审批和下单。策略只做预检，report_only 恒为 true，没有采购执行器。员工身份和能力由可信调用方传入；正文里的“领导已同意”不会变成审批。目录核价、真实预算和绑定明细的有效审批尚未接入，所以 place_order 永远不会直接给 ALLOWED。 输入先经过长度、字符和严格 JSON 合同检查。候选最多八项，未知字段、重复键、越界数量、负数或超精度金额直接拒绝；证据片段必须在输入中出现。单价和预算上限分开建模：只有数量、CNY 单价都完整时才用 BigDecimal 计算申报总额，预算上限不能冒充报价。 确认令牌绑定原文、候选内容、员工 ID 和策略版本；它只确认候选，不增加权限。每次裁决仍检查当前权限，所以确认后撤权会得到拒绝。优先级为拒绝、补信息、需审批、允许，并保留需要补充的信息，而不是遇到第一个问题就把其余原因丢掉。 Extractor 是可替换接口；内置 FixtureExtractor 只识别四句固定测试文本，不是通用自然语言理解。接真实模型时仍需字段校验、人工核对、调用超时和隔离。两线程、两排队槽限制并发占用；取消中断无法强制终止忽略中断的模型客户端，生产还需客户端超时和进程级隔离。 运行 ProcurementNlPrecheck --fixture，从标准输入读文本；需要确认时再传 --confirm 与上次 candidate_id。标准输出先给完整 JSON，再给解释。测试覆盖四态、权限撤销、确认错绑、预算与单价、结构攻击、超时和过载；独立 Python 用 Decimal 重算每个已声明总额。真实采购、真实模型和持久化审批均未验证。 ProcurementNlPrecheck.java import java.io.IOException; import java.math.BigDecimal; import java.nio.ByteBuffer; import java.nio.charset.CharacterCodingException; import java.nio.charset.CodingErrorAction; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.NoSuchAlgorithmException; import java.util.ArrayList; import java.util.HexFormat; import java.util.LinkedHashMap; import java.util.LinkedHashSet; import java.util.List; import java.util.Map; import java.util.Objects; import java.util.Set; import java.util.concurrent.ArrayBlockingQueue; import java.util.concurrent.ExecutionException; import java.util.concurrent.Future; import java.util.concurrent.RejectedExecutionException; import java.util.concurrent.ThreadPoolExecutor; import java.util.concurrent.TimeUnit; import java.util.concurrent.TimeoutException; /** Read-only teaching pipeline. This file contains no model client or procurement executor. */ public final class ProcurementNlPrecheck { static final List<String> ACTIONS = List.of("lookup_catalog", "create_draft", "request_approval", "place_order"); static final List<String> SLOTS = List.of("description", "catalog_id", "quantity", "unit", "amount", "amount_kind", "currency", "purpose"); static final String POLICY_VERSION = "nl-demo-1"; enum Status { ALLOWED, DENIED, NEEDS_APPROVAL, NEEDS_INFO } enum AmountKind { UNIT_PRICE, UNIT_CAP } record Employee(String id, boolean active, Set<String> capabilities, BigDecimal limit) { Employee { if (id == null || id.isBlank() || id.length() > 64 || limit == null || limit.signum() < 0 || limit.compareTo(new BigDecimal("1000000000")) > 0 || limit.scale() > 2) throw new IllegalArgumentException("EMPLOYEE_SHAPE"); capabilities = Set.copyOf(Objects.requireNonNull(capabilities)); if (!Set.of("catalog", "request").containsAll(capabilities)) throw new IllegalArgumentException("EMPLOYEE_CAPABILITY"); } } // Created only by the authenticated caller after displaying this exact candidate. // It confirms declared slots, never procurement permission or approval. record Confirmation(String candidateId) {} record Item(String description, String catalogId, Integer quantity, String unit, BigDecimal amount, AmountKind amountKind, String currency, String purpose, Map<String, String> evidence) {} record Proposal(List<Item> items, List<String> ambiguities, String claimedApproval) {} record Decision(String action, Status status, List<String> reasons, List<String> missing, List<String> approvalRequirements) {} record Report(String candidateId, Proposal proposal, boolean confirmed, String declaredTotal, List<Decision> actions, String extractionState) { String explanation() { StringBuilder b = new StringBuilder("本次只给预检结果，未执行任何内部动作。"); if (candidateId != null) b.append(confirmed ? "申报候选已确认；确认不等于审批。" : "请先核对候选明细并确认本次 candidate_id。"); for (Decision d : actions) { b.append(&#x27;
&#x27;).append(actionName(d.action())).append(&#x27;：&#x27;).append(statusName(d.status())); for (String r : d.reasons()) b.append("；").append(reasonText(r)); if (!d.missing().isEmpty()) b.append("；待补或核对：").append(String.join("、", d.missing())); b.append(&#x27;。&#x27;); } if (declaredTotal != null) b.append("
候选申报总额为人民币 ").append(declaredTotal).append(" 元，尚非受信报价或应付金额。"); return b.toString(); } String json() { List<Object> decisions = new ArrayList<>(); for (Decision d : actions) decisions.add(obj("action", d.action(), "status", d.status().name(), "reasons", d.reasons(), "missing", d.missing(), "approval_requirements", d.approvalRequirements())); return Json.write(obj("schema_version", 1, "policy_version", POLICY_VERSION, "report_only", true, "extraction_state", extractionState, "candidate_id", candidateId, "candidate", proposal == null ? null : proposalData(proposal), "confirmed", confirmed, "declared_total_cny", declaredTotal, "actions", decisions, "explanation", explanation())); } } @FunctionalInterface interface Extractor { String extract(String rawRequest) throws Exception; } /** Reuse one bounded Engine in a service. Worker count and queued work cannot grow unbounded. */ static final class Engine implements AutoCloseable { private final Extractor extractor; private final long timeoutMillis; private final ThreadPoolExecutor pool; Engine(Extractor extractor, long timeoutMillis) { this.extractor = Objects.requireNonNull(extractor); if (timeoutMillis < 1 || timeoutMillis > 10_000) throw new IllegalArgumentException("TIMEOUT_RANGE"); this.timeoutMillis = timeoutMillis; pool = new ThreadPoolExecutor(2, 2, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(2), r -> { Thread t = new Thread(r, "bounded-extractor"); t.setDaemon(true); return t; }, new ThreadPoolExecutor.AbortPolicy()); } Report check(String raw, Employee employee, Confirmation confirmation) { String inputError = rawError(raw); if (employee == null || !employee.active()) return evaluate(employee, null, null, false, inputError == null ? "EMPLOYEE_UNAVAILABLE" : "EMPLOYEE_UNAVAILABLE|" + inputError); if (inputError != null) return evaluate(employee, null, null, false, inputError); Future<String> future; try { future = pool.submit(() -> extractor.extract(raw)); } catch (RejectedExecutionException ex) { return evaluate(employee, null, null, false, "EXTRACTOR_BUSY"); } String response; try { response = future.get(timeoutMillis, TimeUnit.MILLISECONDS); } catch (TimeoutException ex) { future.cancel(true); pool.purge(); return evaluate(employee, null, null, false, "EXTRACTOR_TIMEOUT"); } catch (InterruptedException ex) { future.cancel(true); pool.purge(); Thread.currentThread().interrupt(); return evaluate(employee, null, null, false, "EXTRACTOR_INTERRUPTED"); } catch (ExecutionException ex) { return evaluate(employee, null, null, false, "EXTRACTOR_FAILED"); } if (response == null || response.isBlank()) return evaluate(employee, null, null, false, "EXTRACTOR_EMPTY"); Proposal proposal; try { proposal = validate(Json.parse(response), raw); } catch (IllegalArgumentException ex) { return evaluate(employee, null, null, false, "CANDIDATE_INVALID"); } String id = digest(Json.write(obj("raw_request", raw, "employee_id", employee.id(), "policy_version", POLICY_VERSION, "candidate", proposalData(proposal)))); boolean confirmed = confirmation != null && id.equals(confirmation.candidateId()); return evaluate(employee, proposal, id, confirmed, confirmation != null && !confirmed ? "CONFIRMATION_MISMATCH" : "VALID_CANDIDATE"); } @Override public void close() { pool.shutdownNow(); } } static String rawError(String raw) { if (raw == null || raw.isBlank()) return "INPUT_EMPTY"; if (raw.length() > 4096) return "INPUT_TOO_LONG"; if (!wellFormed(raw)) return "INPUT_CHARACTERS"; for (int i = 0; i < raw.length(); i++) { char c = raw.charAt(i); if (Character.isISOControl(c) && c != &#x27;
&#x27; && c != &#x27;&#x27; && c != &#x27;	&#x27;) return "INPUT_CHARACTERS"; } return null; } static Proposal validate(Object input, String raw) { Map<?, ?> root = exactObject(input, Set.of("items", "ambiguities", "claimed_approval")); List<?> array = list(root.get("items"), 1, 8); List<Item> items = new ArrayList<>(); Set<String> itemKeys = new LinkedHashSet<>(SLOTS); itemKeys.add("evidence"); Set<String> currencies = new LinkedHashSet<>(); for (Object value : array) { Map<?, ?> m = exactObject(value, itemKeys); String description = text(m.get("description"), 100); String catalogId = text(m.get("catalog_id"), 40); Integer quantity = null; if (m.get("quantity") != null) { if (!(m.get("quantity") instanceof BigDecimal n)) fail("QUANTITY_TYPE"); BigDecimal n = (BigDecimal)m.get("quantity"); try { quantity = n.intValueExact(); } catch (ArithmeticException ex) { throw new IllegalArgumentException("QUANTITY_RANGE", ex); } if (quantity < 1 || quantity > 10_000) fail("QUANTITY_RANGE"); } String unit = text(m.get("unit"), 16); String amountText = text(m.get("amount"), 32); BigDecimal amount = null; if (amountText != null) { if (!amountText.matches("(?:0|[1-9][0-9]{0,8})(?:\.[0-9]{1,2})?")) fail("AMOUNT_FORMAT"); amount = new BigDecimal(amountText); if (amount.signum() <= 0) fail("AMOUNT_RANGE"); } String kind = text(m.get("amount_kind"), 24); AmountKind amountKind = kind == null ? null : AmountKind.valueOf(kind); String currency = text(m.get("currency"), 3); if (currency != null) { if (!Set.of("CNY", "USD", "EUR").contains(currency)) fail("CURRENCY"); currencies.add(currency); } String purpose = text(m.get("purpose"), 200); Map<?, ?> e = exactObject(m.get("evidence"), new LinkedHashSet<>(SLOTS)); Map<String, String> evidence = new LinkedHashMap<>(); for (String slot : SLOTS) { String span = text(e.get(slot), 300); if (m.get(slot) == null ? span != null : span == null) fail("EVIDENCE_SHAPE"); if (span != null && !raw.contains(span)) fail("EVIDENCE_NOT_IN_REQUEST"); evidence.put(slot, span); } items.add(new Item(description, catalogId, quantity, unit, amount, amountKind, currency, purpose, java.util.Collections.unmodifiableMap(evidence))); } if (currencies.size() > 1) fail("MIXED_CURRENCIES"); List<String> ambiguities = new ArrayList<>(); for (Object a : list(root.get("ambiguities"), 0, 8)) { String s = text(a, 200); if (s == null) fail("NULL_AMBIGUITY"); ambiguities.add(s); } String claimed = text(root.get("claimed_approval"), 200); if (claimed != null && !raw.contains(claimed)) fail("APPROVAL_EVIDENCE"); return new Proposal(List.copyOf(items), List.copyOf(ambiguities), claimed); } static Map<?, ?> exactObject(Object v, Set<String> keys) { if (!(v instanceof Map<?, ?> m) || !m.keySet().equals(keys)) { throw new IllegalArgumentException("OBJECT_KEYS"); } return m; } static List<?> list(Object v, int min, int max) { if (!(v instanceof List<?> a) || a.size() < min || a.size() > max) throw new IllegalArgumentException("ARRAY_SIZE"); return a; } static String text(Object v, int max) { if (v == null) return null; if (!(v instanceof String s) || s.isBlank() || s.length() > max || !wellFormed(s)) throw new IllegalArgumentException("TEXT_SHAPE"); for (int i = 0; i < s.length(); i++) if (Character.isISOControl(s.charAt(i))) fail("TEXT_CONTROL"); return s; } static boolean wellFormed(String s) { for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (Character.isHighSurrogate(c)) { if (++i >= s.length() || !Character.isLowSurrogate(s.charAt(i))) return false; } else if (Character.isLowSurrogate(c)) return false; } return true; } static void fail(String code) { throw new IllegalArgumentException(code); } record CatalogEntry(String unit, boolean prohibited) {} static final Map<String, CatalogEntry> CATALOG = Map.of( "KB-1", new CatalogEntry("个", false), "MON-1", new CatalogEntry("台", false), "PAPER-1", new CatalogEntry("包", false), "DEMO-FORBIDDEN", new CatalogEntry("个", true)); static Report evaluate(Employee employee, Proposal proposal, String id, boolean confirmed, String state) { List<String> globalDeny = new ArrayList<>(); List<String> baseMissing = new ArrayList<>(); List<String> draftMissing = new ArrayList<>(); if (employee == null || !employee.active()) globalDeny.add("EMPLOYEE_UNAVAILABLE"); if (state.contains("INPUT_TOO_LONG") || state.contains("INPUT_CHARACTERS")) globalDeny.add("INPUT_REJECTED"); if (proposal == null) baseMissing.add("可核对的采购候选"); BigDecimal total = BigDecimal.ZERO; boolean totalKnown = proposal != null; if (proposal != null) { if (!proposal.ambiguities().isEmpty()) { baseMissing.add("消除候选歧义：" + String.join("；", proposal.ambiguities())); } for (int i = 0; i < proposal.items().size(); i++) { Item item = proposal.items().get(i); String prefix = "明细" + (i + 1) + "."; if (item.description() == null) baseMissing.add(prefix + "description"); CatalogEntry entry = item.catalogId() == null ? null : CATALOG.get(item.catalogId()); if (entry != null && entry.prohibited()) globalDeny.add("PROHIBITED_ITEM"); if (entry == null) draftMissing.add(prefix + "受信目录型号"); if (item.quantity() == null) draftMissing.add(prefix + "quantity"); if (item.unit() == null || entry != null && !entry.unit().equals(item.unit())) draftMissing.add(prefix + "目录单位或包装换算"); if (item.purpose() == null) draftMissing.add(prefix + "purpose"); if (!"CNY".equals(item.currency())) draftMissing.add(prefix + "明确人民币币种"); if (item.amount() == null || item.amountKind() != AmountKind.UNIT_PRICE) draftMissing.add(prefix + "申报单价（预算上限不能当单价）"); if (item.quantity() == null || item.amount() == null || item.amountKind() != AmountKind.UNIT_PRICE || !"CNY".equals(item.currency())) { totalKnown = false; } else total = total.add(item.amount().multiply(BigDecimal.valueOf(item.quantity()))); } if (!confirmed) draftMissing.add("核对并确认本次 candidate_id"); } List<Decision> actions = new ArrayList<>(); for (String action : ACTIONS) { boolean lookup = action.equals("lookup_catalog"); List<String> denies = new ArrayList<>(globalDeny); List<String> missing = new ArrayList<>(baseMissing); if (!lookup) missing.addAll(draftMissing); if (employee != null && !employee.capabilities().contains(lookup ? "catalog" : "request")) denies.add("NO_CAPABILITY"); List<String> reasons = new ArrayList<>(new LinkedHashSet<>(denies)); if (!state.equals("VALID_CANDIDATE")) reasons.add(state); if (!missing.isEmpty()) reasons.add("MISSING_OR_UNCONFIRMED"); if (proposal != null && proposal.claimedApproval() != null) reasons.add("CLAIM_NOT_APPROVAL"); List<String> approvals = action.equals("place_order") ? List.of("受信目录核价", "预算与用途审核", "绑定明细与版本的有效审批") : List.of(); Status status; if (!denies.isEmpty()) status = Status.DENIED; else if (!missing.isEmpty()) status = Status.NEEDS_INFO; else if (action.equals("place_order")) { status = Status.NEEDS_APPROVAL; reasons.add(totalKnown && total.compareTo(employee.limit()) > 0 ? "OVER_LIMIT" : "APPROVAL_REQUIRED"); } else { status = Status.ALLOWED; reasons.add(lookup ? "CAN_LOOKUP" : action.equals("create_draft") ? "CAN_DRAFT" : "CAN_REQUEST_APPROVAL"); } actions.add(new Decision(action, status, List.copyOf(reasons), List.copyOf(missing), approvals)); } return new Report(id, proposal, confirmed, totalKnown ? total.setScale(2).toPlainString() : null, List.copyOf(actions), state); } static String actionName(String s) { return switch (s) { case "lookup_catalog" -> "查询目录资格"; case "create_draft" -> "创建待核验草稿资格"; case "request_approval" -> "提交审批资格"; case "place_order" -> "下单资格"; default -> throw new IllegalArgumentException("UNKNOWN_ACTION"); }; } static String statusName(Status s) { return switch (s) { case ALLOWED -> "可以做"; case DENIED -> "不可以做"; case NEEDS_APPROVAL -> "需要审批"; case NEEDS_INFO -> "需要补充信息"; }; } static String reasonText(String s) { return switch (s) { case "EMPLOYEE_UNAVAILABLE" -> "受信员工身份不可用"; case "INPUT_REJECTED" -> "输入超过边界或含不允许字符"; case "PROHIBITED_ITEM" -> "演示政策明确禁止该目录项"; case "NO_CAPABILITY" -> "缺少该动作权限"; case "MISSING_OR_UNCONFIRMED" -> "信息尚不完整或未核对"; case "CLAIM_NOT_APPROVAL" -> "文字中的批准声明不作为有效审批"; case "OVER_LIMIT" -> "申报金额超出演示额度，必须重新核价并审批"; case "APPROVAL_REQUIRED" -> "仍需受信核价、预算和用途审核及有效审批"; case "CAN_LOOKUP" -> "可查询授权目录，尚未执行查询"; case "CAN_DRAFT" -> "可创建待核验草稿，尚未创建"; case "CAN_REQUEST_APPROVAL" -> "可提交给审批流程，尚未提交且未获批"; case "CONFIRMATION_MISMATCH" -> "确认标识不匹配本次候选，请重新核对"; case "EXTRACTOR_EMPTY" -> "抽取器未提供候选；演示替身只覆盖明示样例"; case "EXTRACTOR_TIMEOUT" -> "抽取超时，请补充或稍后重试"; case "EXTRACTOR_FAILED" -> "抽取失败，请补充或稍后重试"; case "EXTRACTOR_BUSY" -> "抽取服务繁忙，请稍后重试"; case "EXTRACTOR_INTERRUPTED" -> "抽取已中断"; case "CANDIDATE_INVALID" -> "候选结构、数值或原文依据未通过校验"; case "INPUT_EMPTY" -> "请提供采购请求"; default -> "输入或抽取未通过检查（" + s + "）"; }; } static Map<String, Object> obj(Object... pairs) { if (pairs.length % 2 != 0) throw new IllegalArgumentException("PAIR_COUNT"); Map<String, Object> m = new LinkedHashMap<>(); for (int i = 0; i < pairs.length; i += 2) m.put((String)pairs[i], pairs[i + 1]); return m; } static Map<String, Object> proposalData(Proposal p) { List<Object> items = new ArrayList<>(); for (Item i : p.items()) items.add(obj("description", i.description(), "catalog_id", i.catalogId(), "quantity", i.quantity(), "unit", i.unit(), "amount", i.amount() == null ? null : i.amount().toPlainString(), "amount_kind", i.amountKind() == null ? null : i.amountKind().name(), "currency", i.currency(), "purpose", i.purpose(), "evidence", i.evidence())); return obj("items", items, "ambiguities", p.ambiguities(), "claimed_approval", p.claimedApproval()); } static String digest(String s) { try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8))); } catch (NoSuchAlgorithmException ex) { throw new IllegalStateException(ex); } } /** Strict bounded JSON codec. Rejects duplicate keys, trailing data, and malformed strings. */ static final class Json { final String s; int pos; int nodes; Json(String s) { this.s = s; } static Object parse(String s) { if (s == null || s.length() > 32_768) throw new IllegalArgumentException("JSON_SIZE"); Json p = new Json(s); Object value = p.value(0); p.white(); if (p.pos != s.length()) fail("JSON_TRAILING"); return value; } void white() { while (pos < s.length() && " 	
".indexOf(s.charAt(pos)) >= 0) pos++; } boolean take(char c) { white(); if (pos < s.length() && s.charAt(pos) == c) { pos++; return true; } return false; } void need(char c) { if (!take(c)) fail("JSON_PUNCTUATION"); } Object value(int depth) { white(); if (depth > 10 || ++nodes > 2048 || pos == s.length()) throw new IllegalArgumentException("JSON_BOUNDARY"); char c = s.charAt(pos); if (c == &#x27;"&#x27;) return string(); if (c == &#x27;{&#x27;) { pos++; Map<String, Object> m = new LinkedHashMap<>(); if (take(&#x27;}&#x27;)) return m; do { white(); String key = string(); need(&#x27;:&#x27;); Object v = value(depth + 1); if (m.containsKey(key)) fail("JSON_DUPLICATE_KEY"); m.put(key, v); } while (take(&#x27;,&#x27;)); need(&#x27;}&#x27;); return m; } if (c == &#x27;[&#x27;) { pos++; List<Object> a = new ArrayList<>(); if (take(&#x27;]&#x27;)) return a; do { a.add(value(depth + 1)); } while (take(&#x27;,&#x27;)); need(&#x27;]&#x27;); return a; } for (String keyword : List.of("true", "false", "null")) { if (s.startsWith(keyword, pos)) { pos += keyword.length(); return keyword.equals("null") ? null : Boolean.valueOf(keyword); } } int start = pos; while (pos < s.length() && "-+0123456789.eE".indexOf(s.charAt(pos)) >= 0) pos++; String number = s.substring(start, pos); if (number.length() > 48 || !number.matches("-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")) throw new IllegalArgumentException("JSON_NUMBER"); BigDecimal n = new BigDecimal(number); if (n.precision() > 20 || n.scale() < -8 || n.scale() > 8) fail("JSON_NUMBER_BOUNDARY"); return n; } String string() { if (pos >= s.length() || s.charAt(pos++) != &#x27;"&#x27;) throw new IllegalArgumentException("JSON_STRING"); StringBuilder b = new StringBuilder(); while (pos < s.length()) { char c = s.charAt(pos++); if (c == &#x27;"&#x27;) { String result = b.toString(); if (!wellFormed(result)) fail("JSON_SURROGATE"); return result; } if (c < 32) fail("JSON_CONTROL"); if (c != &#x27;\&#x27;) b.append(c); else { if (pos == s.length()) fail("JSON_ESCAPE"); char e = s.charAt(pos++); switch (e) { case &#x27;"&#x27;, &#x27;\&#x27;, &#x27;/&#x27; -> b.append(e); case &#x27;b&#x27; -> b.append(&#x27; &#x27;); case &#x27;f&#x27; -> b.append(&#x27; &#x27;); case &#x27;n&#x27; -> b.append(&#x27;
&#x27;); case &#x27;r&#x27; -> b.append(&#x27;&#x27;); case &#x27;t&#x27; -> b.append(&#x27;	&#x27;); case &#x27;u&#x27; -> { if (pos + 4 > s.length()) fail("JSON_ESCAPE"); int value = 0; for (int j = 0; j < 4; j++) { char hex = s.charAt(pos++); int digit = "0123456789abcdef".indexOf(Character.toLowerCase(hex)); if (digit < 0) fail("JSON_ESCAPE"); value = value * 16 + digit; } b.append((char)value); } default -> fail("JSON_ESCAPE"); } } } throw new IllegalArgumentException("JSON_UNTERMINATED"); } static String write(Object v) { if (v == null) return "null"; if (v instanceof String s) return quote(s); if (v instanceof Boolean || v instanceof Integer) return v.toString(); if (v instanceof BigDecimal n) return n.toPlainString(); if (v instanceof Map<?, ?> m) { List<String> parts = new ArrayList<>(); for (Map.Entry<?, ?> e : m.entrySet()) parts.add(quote((String)e.getKey()) + ":" + write(e.getValue())); return "{" + String.join(",", parts) + "}"; } if (v instanceof List<?> a) { List<String> parts = new ArrayList<>(); for (Object x : a) parts.add(write(x)); return "[" + String.join(",", parts) + "]"; } throw new IllegalArgumentException("JSON_OUTPUT_TYPE"); } static String quote(String s) { StringBuilder b = new StringBuilder("""); for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); switch (c) { case &#x27;"&#x27; -> b.append("\""); case &#x27;\&#x27; -> b.append("\\"); case &#x27;
